INSERT INTO questions (section_id, topic, stem, choices, correct_index, explanation, difficulty, cognitive_level)
VALUES

-- Q1: hard / L4 — Section 736(a) vs 736(b) payments to retiring general partner
(3, 'Partnerships', 'Partner Donovan retires from a three-person general partnership. The partnership agreement provides for $180,000 in payments: $120,000 for Donovan''s share of partnership property (including $20,000 attributable to goodwill not specified in the agreement) and $60,000 for past services. Evaluate how these payments are classified under Section 736.', '["$100,000 is Section 736(b) property payments and $80,000 is Section 736(a) ordinary income to Donovan", "$120,000 is Section 736(b) property payments and $60,000 is Section 736(a) ordinary income", "The entire $180,000 is Section 736(b) because all payments relate to Donovan''s partnership interest", "$100,000 is Section 736(b), $60,000 is Section 736(a), and $20,000 is separately taxed as capital gain"]'::jsonb, 0, 'Under Section 736, payments to a retiring general partner are classified as 736(b) (property payments, capital treatment) or 736(a) (ordinary income). For general partnerships, goodwill not specified in the agreement is excluded from 736(b) and treated as 736(a). The $100,000 of property payments (excluding $20,000 unspecified goodwill) is 736(b), while $20,000 goodwill plus $60,000 for services equals $80,000 of 736(a). Choice B incorrectly treats unspecified goodwill as a property payment under 736(b).', 'hard', 4),

-- Q2: hard / L4 — Three-layer loss limitation sequential analysis
(3, 'Partnerships', 'Partner Mercer has an outside basis of $90,000, an at-risk amount of $70,000, and no passive income. Mercer does not materially participate in the partnership. Her distributive share of partnership loss is $100,000. Evaluate the loss allowed at each limitation level and the total amount suspended under each rule.', '["$10,000 suspended at basis, $20,000 suspended at at-risk, and $70,000 deductible against ordinary income", "$10,000 suspended at basis, $20,000 suspended at at-risk, and $70,000 suspended under passive activity rules", "$30,000 total suspended at basis with $70,000 deductible", "$10,000 suspended at basis and $90,000 suspended under passive activity rules"]'::jsonb, 1, 'Under IRC Sections 704(d), 465, and 469, partnership losses face three sequential limitations: basis, at-risk, and passive activity. First, $100,000 is limited to Mercer''s $90,000 basis, suspending $10,000. The $90,000 is then limited to the $70,000 at-risk amount, suspending $20,000. Finally, the $70,000 cannot offset non-passive income because Mercer does not materially participate, so all $70,000 is suspended as a passive loss. Choice A incorrectly allows the $70,000 as a deduction despite non-material participation.', 'hard', 4),

-- Q3: easy / L1 — Partnership informational return filing requirement
(3, 'Partnerships', 'What informational return is a partnership required to file with the IRS?', '["Form 1120", "Form 1120-S", "Form 1065", "Schedule C"]'::jsonb, 2, 'Under IRC Section 6031, a partnership files Form 1065, U.S. Return of Partnership Income, as an informational return. The partnership itself pays no entity-level tax; income passes through to partners via Schedule K-1. Choice A (Form 1120) is for C corporations, and Choice B (Form 1120-S) is for S corporations.', 'easy', 1),

-- Q4: hard / L3 — Disguised sale under Section 707(a)(2)(B)
(3, 'Partnerships', 'Partner Norton contributes land worth $500,000 (basis $200,000) to Hillcrest Partners LLC on March 1, 2026. On April 15, 2026, the partnership distributes $500,000 cash to Norton. Under Section 707(a)(2)(B), how should this transaction be recharacterized?', '["As a tax-free contribution followed by a separate tax-free distribution", "As a guaranteed payment of $500,000 taxable as ordinary income", "As a partial sale of $200,000 with the remaining $300,000 treated as a distribution", "As a disguised sale, with Norton recognizing $300,000 of gain"]'::jsonb, 3, 'Under Section 707(a)(2)(B) and Treas. Reg. 1.707-3, a contribution followed by a related distribution within two years is presumed to be a disguised sale. Norton is treated as selling the land for $500,000, recognizing $300,000 gain ($500,000 amount realized minus $200,000 basis). Choice A ignores the disguised sale presumption that applies when a distribution is closely related in time to the contribution.', 'hard', 3),

-- Q5: medium / L2 — Section 709 organizational vs syndication expenses
(3, 'Partnerships', 'Ridgewood Partners LLC incurs $4,000 in legal fees for drafting the partnership agreement and $15,000 in brokerage commissions for selling limited partnership interests in 2026. How are these costs treated under Section 709?', '["$19,000 is amortized over 180 months beginning with the month the partnership starts business", "$4,000 is amortized over 180 months and $15,000 is deducted currently as a business expense", "Both amounts are currently deductible as ordinary and necessary business expenses", "$4,000 is deductible in the first year as an organizational expense and $15,000 must be capitalized permanently as a syndication expense"]'::jsonb, 3, 'Under Section 709(b), organizational expenses up to $5,000 are deductible in the first year (with phase-out above $50,000 total), and the excess is amortized over 180 months. Since $4,000 is under the $5,000 threshold, it is fully deductible. Syndication expenses (selling partnership interests) are never deductible or amortizable under Section 709(a) and must be permanently capitalized. Choice A incorrectly treats syndication expenses as amortizable.', 'medium', 2),

-- Q6: medium / L3 — At-risk limitation with qualified nonrecourse financing
(3, 'Partnerships', 'Partner Gibson invests $50,000 cash in a real estate partnership. Her share of partnership liabilities includes $80,000 of qualified nonrecourse financing secured by the property and $30,000 of general nonrecourse debt. Under Section 465, what is Gibson''s at-risk amount?', '["$130,000", "$160,000", "$50,000", "$80,000"]'::jsonb, 0, 'Under Section 465(b)(6), the at-risk amount includes cash contributed plus qualified nonrecourse financing for real estate activities. Qualified nonrecourse financing ($80,000) is included because it is secured by real property used in the activity, but the $30,000 general nonrecourse debt is excluded. Gibson''s at-risk amount is $50,000 + $80,000 = $130,000. Choice B incorrectly includes all nonrecourse debt, ignoring the distinction between qualified and general nonrecourse financing.', 'medium', 3),

-- Q7: medium / L2 — Constructive distribution from liability reduction
(3, 'Partnerships', 'Partner Wallace has a 40% interest in Sycamore Partners LP. Wallace''s outside basis is $50,000, which includes her $80,000 share of the partnership''s $200,000 recourse liabilities. The partnership repays the entire $200,000 loan. What is Wallace''s outside basis and recognized gain?', '["Outside basis of $0 and no recognized gain", "Outside basis of $50,000 and no recognized gain", "Outside basis of $0 and $30,000 of recognized capital gain", "Outside basis of $0 and $80,000 of recognized capital gain"]'::jsonb, 2, 'Under Section 752(b), a decrease in a partner''s share of partnership liabilities is treated as a deemed cash distribution. Wallace''s $80,000 liability decrease exceeds her $50,000 basis by $30,000. Under Section 731(a)(1), deemed cash distributions exceeding outside basis trigger capital gain. Wallace''s basis reduces to $0 and she recognizes $30,000 capital gain. Choice D incorrectly treats the entire liability reduction as gain rather than the excess over basis.', 'medium', 2),

-- Q8: medium / L3 — Passive activity loss limitation with rental real estate exception phase-out
(3, 'Partnerships', 'Partner Ramsey actively participates in a rental real estate partnership and has AGI of $110,000. Her distributive share of rental loss is $35,000 with no other passive income. Under Section 469, what is the maximum rental loss Ramsey can deduct?', '["$35,000, because active participation allows full deduction of rental losses", "$25,000, because the rental real estate exception caps the deduction at that amount", "$0, because all rental activity losses are passive regardless of participation", "$20,000, because the $25,000 exception is reduced by $5,000 due to the AGI phase-out"]'::jsonb, 3, 'Under Section 469(i), taxpayers who actively participate in rental real estate may deduct up to $25,000 of rental losses against non-passive income. This allowance is reduced by 50% of AGI exceeding $100,000. With $110,000 AGI, the phase-out is ($110,000 − $100,000) × 50% = $5,000, leaving a $20,000 allowance. The remaining $15,000 loss is suspended. Choice B ignores the AGI phase-out that reduces the $25,000 exception.', 'medium', 3),

-- Q9: hard / L4 — Family partnership rules under Section 704(e)
(3, 'Partnerships', 'Harrison operates a manufacturing business as a partnership. He gifts a 40% capital interest valued at $200,000 to his 19-year-old daughter Riley, who performs no services. Partnership income is $500,000 before any allocation, and reasonable compensation for Harrison''s services is $200,000. Evaluate Riley''s maximum income allocation under Section 704(e).', '["$200,000, because Riley holds a valid 40% partnership interest", "Riley receives nothing because donees who perform no services cannot be partners", "$160,000, which is 40% of $400,000 after deducting a $100,000 partial services allocation", "$120,000, which is 40% of the $300,000 remaining after Harrison''s $200,000 reasonable compensation"]'::jsonb, 3, 'Under Section 704(e)(2), when a partnership interest is acquired by gift and capital is a material income-producing factor, reasonable compensation for the donor''s services must first be allocated before determining the donee''s share. After deducting Harrison''s $200,000 reasonable compensation, $300,000 remains. Riley''s maximum allocation is 40% × $300,000 = $120,000. Choice A ignores the requirement to first allocate reasonable compensation for services rendered by the donor partner.', 'hard', 4),

-- Q10: medium / L2 — Basis limitation on loss deduction with carryforward
(3, 'Partnerships', 'Partner Keane has an outside basis of $35,000 in Brightline Partners LP. Her distributive share of the partnership''s ordinary loss for the year is $50,000. How much of the loss may Keane deduct, and what happens to the remainder?', '["Keane deducts $35,000 and the remaining $15,000 is suspended until her basis is restored", "Keane deducts the full $50,000 and her basis becomes negative $15,000", "Keane deducts $35,000 and the remaining $15,000 is permanently disallowed", "Keane deducts $0 because the loss exceeds her outside basis"]'::jsonb, 0, 'Under Section 704(d), a partner''s distributive share of loss is deductible only to the extent of the partner''s outside basis. Keane''s $50,000 loss is limited to her $35,000 basis. The excess $15,000 is suspended and carries forward indefinitely, becoming deductible when Keane''s basis increases through income allocations, contributions, or additional liabilities. Choice C incorrectly states the excess is permanently disallowed.', 'medium', 2),

-- Q11: medium / L2 — Partner's holding period tacking for contributed capital asset
(3, 'Partnerships', 'Partner Reeves contributes a capital asset she has held for three years to Cascade Partners LLC in exchange for a 30% interest on June 1, 2026. What is Reeves''s holding period for her partnership interest?', '["It begins on June 1, 2026, the date of the contribution", "It includes the three-year holding period of the contributed capital asset", "It begins on the date the partnership was originally formed", "It is automatically classified as long-term regardless of when the asset was acquired"]'::jsonb, 1, 'Under Section 1223(1), when a partner contributes a capital asset or Section 1231 property in a Section 721 exchange, the holding period of the partnership interest includes (tacks onto) the holding period of the contributed property. Since Reeves contributed a capital asset held for three years, her partnership interest holding period includes that time. Choice A incorrectly starts a new holding period, ignoring the tacking rule for contributed capital assets.', 'medium', 2),

-- Q12: easy / L1 — Definition of deficit restoration obligation
(3, 'Partnerships', 'In partnership taxation, what is a deficit restoration obligation?', '["A partner''s agreement to restore a negative capital account balance upon partnership liquidation", "A requirement that the partnership restore any tax losses to the IRS upon audit", "An obligation to return excess distributions to the partnership within 90 days", "A requirement that partners maintain minimum capital contributions at all times"]'::jsonb, 0, 'Under Treas. Reg. Section 1.704-1(b)(2)(ii)(b), a deficit restoration obligation is a partner''s commitment to contribute cash to restore a deficit (negative) capital account balance upon liquidation. This is one of the requirements for a special allocation to have economic effect under Section 704(b). Choice C confuses this concept with distribution clawback rules rather than the capital account restoration requirement.', 'easy', 1),

-- Q13: easy / L1 — Character of guaranteed payments for use of capital
(3, 'Partnerships', 'What type of income does a partner recognize when receiving guaranteed payments for the use of capital?', '["Capital gain income", "Tax-exempt interest income", "Ordinary income", "Qualified dividend income"]'::jsonb, 2, 'Under Section 707(c), guaranteed payments to a partner for the use of capital are treated as ordinary income to the receiving partner, just like guaranteed payments for services. They are reported on the partner''s Schedule K-1 and are subject to self-employment tax. Choice A is incorrect because guaranteed payments never receive capital gain treatment regardless of whether they compensate for services or capital use.', 'easy', 1),

-- Q14: hard / L4 — Section 704(c)(1)(B) seven-year distribution rule
(3, 'Partnerships', 'Partner Whitfield contributes equipment with a basis of $50,000 and FMV of $120,000 to a three-equal-partner partnership. Two years later, the partnership distributes the equipment to Partner Yates rather than Whitfield. Evaluate the tax consequences to Whitfield under Section 704(c)(1)(B).', '["No gain is recognized because the equipment was distributed rather than sold by the partnership", "Yates recognizes $70,000 gain because she received property with a built-in gain", "Whitfield recognizes $23,333 of gain representing one-third of the built-in gain", "Whitfield recognizes $70,000 gain as if the equipment were sold at its contribution-date FMV"]'::jsonb, 3, 'Under Section 704(c)(1)(B), if contributed property with built-in gain is distributed to another partner within seven years, the contributing partner recognizes the remaining built-in gain ($120,000 − $50,000 = $70,000). This anti-abuse rule prevents partners from using distributions to shift pre-contribution gain away from the contributor without triggering tax. Choice A incorrectly assumes distributions never trigger gain; Section 704(c)(1)(B) overrides the general nonrecognition rule.', 'hard', 4),

-- Q15: medium / L3 — Mid-year entry with proration method under Section 706(d)
(3, 'Partnerships', 'Chen joins an existing two-person equal partnership as a one-third partner on July 1, 2026. The partnership earns $180,000 of ordinary income for the full year and uses the proration method. What is Chen''s distributive share of partnership income for 2026?', '["$30,000", "$60,000", "$90,000", "$45,000"]'::jsonb, 0, 'Under Section 706(d)(1), when a partner''s interest varies during the year, income must be allocated considering the varying interests. Using the proration method, Chen''s share is one-third of income for the portion of the year she was a partner: $180,000 × 1/3 × 6/12 = $30,000. Choice B incorrectly allocates a full year''s share despite Chen joining mid-year. The interim closing of the books method would produce different results if income was earned unevenly.', 'medium', 3),

-- Q16: medium / L2 — Tax-exempt income and nondeductible expenses in basis adjustments
(3, 'Partnerships', 'Partner Lopez has a beginning outside basis of $100,000. During the year, her distributive share includes $40,000 ordinary income, $5,000 tax-exempt interest, $10,000 ordinary loss, and $3,000 of nondeductible fines. What is Lopez''s outside basis at year-end?', '["$130,000, because tax-exempt income and nondeductible fines are both excluded from basis calculations", "$132,000", "$127,000, because tax-exempt income does not increase basis", "$135,000, because nondeductible fines do not reduce basis"]'::jsonb, 1, 'Under Section 705(a), outside basis is increased by all income items including tax-exempt income ($5,000) and decreased by losses ($10,000) and nondeductible noncapital expenditures ($3,000). Basis = $100,000 + $40,000 + $5,000 − $10,000 − $3,000 = $132,000. Choice A incorrectly excludes both items, but Section 705 requires tax-exempt income and nondeductible expenses to be reflected in basis to preserve their character.', 'medium', 2),

-- Q17: easy / L1 — No control requirement for Section 721
(3, 'Partnerships', 'Unlike Section 351 for corporations, what requirement does Section 721 NOT impose for tax-free partnership contributions?', '["A requirement that property rather than services be contributed", "A requirement that the contributing party receive a partnership interest in exchange", "A requirement that the contribution be made to a domestic entity", "A control requirement for the contributing partners"]'::jsonb, 3, 'Under Section 721, any contribution of property to a partnership in exchange for a partnership interest is tax-free with no requirement that the contributing partners control the partnership. This differs from Section 351, which requires transferors to control at least 80% of the corporation immediately after transfer. Choice A is incorrect because Section 721 does require property (not services) for nonrecognition treatment.', 'easy', 1),

-- Q18: medium / L3 — Section 737 precontribution gain on distribution of other property
(3, 'Partnerships', 'Partner Owen contributed land with a basis of $60,000 and FMV of $150,000 to MapleCrest Partners LLC for a 50% interest. Owen''s outside basis is $60,000. Three years later, the partnership distributes other property with a FMV of $100,000 to Owen in a current distribution. Under Section 737, what gain must Owen recognize?', '["$90,000, the full precontribution gain on the contributed land", "$30,000, the distributed property''s appreciation over its basis", "$40,000, the excess of the distributed property''s FMV over Owen''s outside basis", "$0, because distributions of property other than the contributed property do not trigger gain"]'::jsonb, 2, 'Under Section 737, when a partner who contributed appreciated property receives a distribution of other property within seven years, gain equals the lesser of (1) the FMV of distributed property minus the partner''s outside basis ($100,000 − $60,000 = $40,000), or (2) the net precontribution gain ($90,000). Owen recognizes $40,000. Choice D incorrectly assumes Section 737 does not apply; this anti-abuse rule prevents tax-free extraction of precontribution gain through distributions of other property.', 'medium', 3),

-- Q19: easy / L1 — Schedule K-1 purpose
(3, 'Partnerships', 'What form does a partnership use to report each partner''s share of income, deductions, and credits?', '["Form W-2", "Form 1099-MISC", "Form 1099-DIV", "Schedule K-1 (Form 1065)"]'::jsonb, 3, 'Under IRC Section 6031, a partnership reports each partner''s distributive share of income, deductions, gains, losses, and credits on Schedule K-1 (Form 1065). Each partner receives a K-1 and reports those items on their individual return. Choice A (Form W-2) reports employee wages, and Choice B (Form 1099-MISC) reports payments to independent contractors—neither applies to partnership allocations.', 'easy', 1),

-- Q20: easy / L2 — Qualified nonrecourse financing in at-risk calculation
(3, 'Partnerships', 'Partner Ellis contributes $75,000 cash to a real estate partnership. Her share of the partnership''s debt includes $50,000 of qualified nonrecourse financing secured by real property and $20,000 of general nonrecourse debt. What is Ellis''s at-risk amount under Section 465?', '["$125,000", "$145,000", "$75,000", "$95,000"]'::jsonb, 0, 'Under Section 465(b)(6), qualified nonrecourse financing secured by real property is included in the at-risk amount for real estate activities. Ellis''s at-risk amount is $75,000 cash + $50,000 qualified nonrecourse financing = $125,000. The $20,000 general nonrecourse debt is excluded because it does not meet the qualified nonrecourse financing requirements. Choice B incorrectly includes all liabilities in the at-risk calculation.', 'easy', 2),

-- Q21: medium / L2 — Material participation 500-hour test and passive loss classification
(3, 'Partnerships', 'Partner Dalton spent 450 hours working in a partnership''s restaurant business during 2026. Two non-owner employees each spent 600 hours. Dalton''s distributive share of partnership loss is $40,000. Under Section 469, is the loss passive?', '["No, because any participation over 100 hours qualifies as material participation", "No, because Dalton manages the business and is a general partner", "Yes, but Dalton can deduct $25,000 under the rental real estate exception", "Yes, because Dalton fails the 500-hour test and other individuals participated more"]'::jsonb, 3, 'Under Section 469 and Temp. Reg. 1.469-5T, material participation requires meeting one of seven tests. The most common test requires more than 500 hours. With 450 hours, Dalton fails this test. The 100-hour test also fails because other individuals participated more. Since Dalton does not materially participate, the $40,000 loss is passive and can only offset passive income. Choice A incorrectly assumes 100 hours is sufficient regardless of others'' participation levels.', 'medium', 2),

-- Q22: easy / L1 — Partnership required taxable year under Section 706(b)
(3, 'Partnerships', 'What is a partnership''s required taxable year under Section 706(b)?', '["The fiscal year that results in the greatest tax deferral for the partners", "The taxable year of the majority-interest partners", "Always the calendar year regardless of partners'' tax years", "Any year elected by a majority vote of the partners"]'::jsonb, 1, 'Under Section 706(b), a partnership must adopt the taxable year of its majority-interest partners (partners owning more than 50% of profits and capital). If no majority interest exists, the partnership uses the year of all principal partners. If no common year, the least aggregate deferral method applies. Choice C is incorrect because a specific year is required only if earlier tests fail.', 'easy', 1),

-- Q23: hard / L4 — Section 754 election consequences for multiple partners
(3, 'Partnerships', 'Pineview Partners LP has four equal partners. Partner Abbott purchased her 25% interest for $400,000 when the partnership''s total inside basis was $1,200,000. The partnership makes a Section 754 election. Partner Briggs, who purchased his interest years ago at a discount ($200,000 when his share of inside basis was $300,000), argues against the election. Evaluate the consequences for each partner.', '["The election benefits Abbott with a $100,000 step-up but forces Briggs to take a $100,000 step-down immediately", "The election benefits Abbott with a $100,000 step-up and Briggs must amend prior returns to reflect his step-down", "The election benefits Abbott with a $100,000 step-up; Briggs is currently unaffected but any future transfer of his interest would trigger a step-down for the new buyer", "The election applies only to Abbott because it was specifically made for her benefit"]'::jsonb, 2, 'Under Sections 754 and 743(b), the election creates a basis adjustment only for the specific transferee. Abbott receives a $100,000 step-up ($400,000 outside basis minus $300,000 share of inside basis). Briggs receives no retroactive adjustment because 743(b) applies only at the time of transfer. However, the ongoing Section 754 election means any future sale of Briggs''s interest would create a 743(b) adjustment for the buyer. Choice A incorrectly states Briggs receives an immediate step-down.', 'hard', 4),

-- Q24: medium / L2 — Substantially appreciated inventory test for Section 751(b)
(3, 'Partnerships', 'Cascade Partners LP distributes inventory disproportionately to Partner Flynn. The partnership''s total inventory has a FMV of $300,000 and a basis of $240,000. For Section 751(b) distribution purposes, is the inventory substantially appreciated?', '["Yes, because the FMV of $300,000 exceeds 120% of the $240,000 basis", "No, because the FMV must exceed 150% of basis to be substantially appreciated", "Yes, because all partnership inventory is automatically classified as a hot asset", "No, because the $60,000 appreciation is insufficient to trigger hot asset treatment"]'::jsonb, 0, 'Under Section 751(b)(3), inventory is substantially appreciated for distribution purposes when its FMV exceeds 120% of the partnership''s adjusted basis. Here, 120% × $240,000 = $288,000, and the $300,000 FMV exceeds this threshold (125% appreciation). Section 751(b) treats the disproportionate distribution as a taxable exchange triggering ordinary income. Choice C is incorrect because for distributions under 751(b), inventory must meet the 120% appreciation test.', 'medium', 2),

-- Q25: medium / L3 — Section 1245 recapture as unrealized receivable in hot assets
(3, 'Partnerships', 'Westbrook Partners LP owns equipment with a basis of $60,000, accumulated depreciation of $100,000, and a FMV of $200,000 (original cost $160,000). Partner Grey sells his 25% interest. For Section 751 purposes, what amount of unrealized receivables is attributable to Grey''s share of the equipment?', '["$35,000, based on Grey''s share of the total gain on the equipment", "$15,000, based on the difference between FMV and original cost", "$25,000, based on Grey''s share of Section 1245 depreciation recapture", "$50,000, based on Grey''s share of the equipment''s FMV"]'::jsonb, 2, 'Under Section 751(c), unrealized receivables include potential Section 1245 recapture. The equipment has $100,000 of accumulated depreciation subject to recapture (the lesser of depreciation taken or gain on sale). Grey''s 25% share equals $25,000 of ordinary income upon sale of his interest. The remaining gain beyond recapture is capital gain. Choice A incorrectly calculates Grey''s share of total gain rather than isolating the Section 1245 recapture component.', 'medium', 3),

-- Q26: medium / L2 — Liquidating distribution property basis substitution rule
(3, 'Partnerships', 'Partner Bishop receives a liquidating distribution consisting solely of land with a partnership inside basis of $40,000 and FMV of $70,000. Bishop''s outside basis immediately before the distribution is $55,000. What is Bishop''s basis in the land?', '["$40,000, the partnership''s inside basis in the land", "$55,000, Bishop''s outside basis before the distribution", "$70,000, the land''s fair market value", "$45,000, the average of inside basis and outside basis"]'::jsonb, 1, 'Under Section 732(b), in a liquidating distribution, the distributee partner''s basis in the distributed property equals the partner''s remaining outside basis, regardless of the partnership''s inside basis. Bishop''s $55,000 outside basis becomes the land''s basis, creating a $15,000 step-up from the $40,000 inside basis. Choice A incorrectly applies the current distribution rule under Section 732(a), which limits basis to inside basis.', 'medium', 2),

-- Q27: medium / L3 — Capital account maintenance required for special allocations
(3, 'Partnerships', 'Oak Valley Partners LP allocates all $80,000 of depreciation deductions to Partner Holt, a 50% partner, while splitting $200,000 of ordinary income equally. The partnership does not maintain capital accounts under the Treasury Regulations. How should the IRS treat Holt''s depreciation allocation under Section 704(b)?', '["Respect the allocation because it was agreed upon by all partners in writing", "Respect the allocation because Holt bears greater economic risk as a 50% partner", "Reallocate the depreciation 50/50 based on Holt''s partnership interest because the capital account requirement is not met", "Disallow the entire depreciation deduction because the partnership failed to maintain capital accounts"]'::jsonb, 2, 'Under Section 704(b) and Treas. Reg. 1.704-1(b)(2), a special allocation must have substantial economic effect, which requires capital accounts maintained in accordance with the regulations. Without proper capital accounts, the allocation lacks economic effect. The IRS reallocates depreciation based on partners'' interests in the partnership—here, 50/50. Choice A incorrectly assumes partner agreement alone validates a special allocation without meeting the regulatory requirements for economic effect.', 'medium', 3),

-- Q28: easy / L1 — Partnership entity-level tax status
(3, 'Partnerships', 'What federal income tax does a partnership pay at the entity level?', '["None; a partnership is a pass-through entity that pays no entity-level income tax", "A flat 21% corporate income tax on all partnership income", "Income tax only on undistributed earnings retained by the partnership", "Self-employment tax on the partnership''s net income"]'::jsonb, 0, 'Under Subchapter K of the IRC, a partnership is a pass-through entity that files an informational return (Form 1065) but pays no federal income tax at the entity level. All income, deductions, and credits pass through to the individual partners via Schedule K-1. Choice B describes C corporation taxation under Section 11, which imposes a 21% flat rate at the entity level.', 'easy', 1),

-- Q29: medium / L3 — Death of partner and Section 1014 basis step-up
(3, 'Partnerships', 'Partner Drake dies on August 15, 2026, holding a 25% interest in Pinecrest Partners LP. Drake''s outside basis was $80,000, and the FMV of the interest at death is $200,000. Drake''s estate inherits the partnership interest. What is the estate''s outside basis in the inherited interest under Section 1014?', '["$80,000, Drake''s original outside basis at the time of death", "$200,000, the fair market value at the date of death", "$140,000, the average of the basis and fair market value", "$80,000, plus any income allocated through the date of death"]'::jsonb, 1, 'Under Section 1014(a), property acquired from a decedent receives a stepped-up basis equal to the fair market value at the date of death. Drake''s estate receives the partnership interest with a $200,000 basis, eliminating $120,000 of unrealized appreciation. If Pinecrest has a Section 754 election in effect, a corresponding 743(b) adjustment would align the inside basis. Choice D incorrectly applies ongoing basis adjustment rules rather than the Section 1014 step-up.', 'medium', 3),

-- Q30: easy / L1 — Definition of pass-through entity for partnerships
(3, 'Partnerships', 'What does it mean for a partnership to be classified as a pass-through entity?', '["The partnership must distribute all income to partners within 90 days of year-end", "Income and losses flow through to individual partners who report them on their own tax returns", "The partnership pays tax first and partners receive after-tax distributions", "Partners are not personally liable for any partnership debts or obligations"]'::jsonb, 1, 'Under Subchapter K of the IRC, a partnership is a pass-through entity, meaning it does not pay entity-level income tax. Instead, all items of income, gain, loss, deduction, and credit pass through to partners via Schedule K-1, and each partner reports these items on their individual return. Choice C describes double taxation applicable to C corporations, not partnerships.', 'easy', 1)
;

COMMIT;
